### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we shift the `id` and `size` into their respective bit positions (0-3 for ID, 4-6 for size) and combine them using bitwise OR. We then write the resulting 7-bit integer into the `Uint8Array` at the current offset.
2.  **Unpacking**: We read bytes from the `Uint8Array`. Since the data is packed tightly, we extract the bits using bitwise masking (`& 0x0F` for ID, `& 0x07` for size) and shifting.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array (ArrayBuffer).
 * 
 * @param {Array} entities - Array of objects with { id, size }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
  if (!entities || entities.length === 0) {
    return new Uint8Array(0);
  }

  // Calculate total bytes needed. 
  // 7 bits per entity. 8 bits per byte. 
  // We need ceil(totalBits / 8) bytes.
  const totalBits = entities.length * 7;
  const byteLength = Math.ceil(totalBits / 8);

  const buffer = new Uint8Array(byteLength);
  let offset = 0;

  for (const entity of entities) {
    // Ensure fields are integers
    const id = Number(entity.id);
    const size = Number(entity.size);

    // Combine fields into a 7-bit integer
    // ID takes bits 0-3 (4 bits)
    // Size takes bits 4-6 (3 bits)
    const packedValue = (id & 0x0F) | ((size & 0x07) << 4);

    // Write the byte to the buffer
    buffer[offset] = packedValue;
    offset++;
  }

  return buffer;
}

/**
 * Unpacks a Uint8Array back into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id, size }
 */
function unpackEntities(buffer) {
  const entities = [];
  let offset = 0;

  while (offset < buffer.length) {
    const byte = buffer[offset];

    // Extract ID (bits 0-3)
    const id = byte & 0x0F;

    // Extract Size (bits 4-6)
    const size = (byte >> 4) & 0x07;

    entities.push({ id, size });

    // Move to next byte
    offset++;
  }

  return entities;
}

